print(f'Total transitions: {len(transitions)}')
errors = 0
for ei, ef, eg_approx, gl, ri in transitions:
    idx = gl - 1
    line = lines[idx]
    is_g = (' 34CL  G ' in line)
    eg_actual = line[9:19].strip() if is_g else '???'
    # Find cG RI$ in next lines
    ri_lines = []
    for i in range(idx+1, min(idx+12, len(lines))):
        if ' 34CL  G ' in lines[i] or ' 34CL  L ' in lines[i]:
            break
        if 'cG RI$' in lines[i]:
            ri_lines.append(lines[i].rstrip())
    ri_status = 'HAS_RI' if ri_lines else 'NO_RI'
    ri_tag = None
    if ri_lines:
        r = ri_lines[0]
        if 'weighted average' in r:
            ri_tag = 'WA'
        elif 'unweighted average' in r:
            ri_tag = 'UWA'
        else:
            ri_tag = 'OTHER/FROM'
    if not is_g:
        print(f'ERROR Ei={ei},Ef={ef}: L{gl} is NOT a G-record!')
        errors += 1
    else:
        print(f'OK Ei={ei:4d},Ef={ef:4d},Eg~{eg_approx:4d} -> L{gl} G={eg_actual:10s} {ri_status}{"/"+ri_tag if ri_tag else ""}')
print(f'\nErrors: {errors}')
